CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE teams(id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, color TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE players(id INTEGER PRIMARY KEY, team_id INTEGER NOT NULL REFERENCES teams(id), name TEXT NOT NULL);
CREATE TABLE player_profiles(player_id INTEGER PRIMARY KEY REFERENCES players(id), positions TEXT NOT NULL DEFAULT '[]', stamina INTEGER CHECK(stamina BETWEEN 1 AND 5), aggression INTEGER CHECK(aggression BETWEEN 1 AND 5), attack INTEGER CHECK(attack BETWEEN 1 AND 5), defense INTEGER CHECK(defense BETWEEN 1 AND 5), overall INTEGER CHECK(overall BETWEEN 1 AND 5), comment TEXT NOT NULL DEFAULT '');
CREATE TABLE team_preferences(user_id INTEGER PRIMARY KEY REFERENCES users(id), team_id INTEGER REFERENCES teams(id));
CREATE TABLE team_transfers(id INTEGER PRIMARY KEY, team_id INTEGER NOT NULL REFERENCES teams(id), sender_id INTEGER NOT NULL REFERENCES users(id), recipient_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX one_pending_transfer ON team_transfers(team_id) WHERE status='pending';
CREATE TABLE player_chemistry(
    player_a INTEGER NOT NULL REFERENCES players(id), player_b INTEGER NOT NULL REFERENCES players(id),
    kind TEXT NOT NULL CHECK(kind IN ('good','bad')), PRIMARY KEY(player_a,player_b), CHECK(player_a < player_b));
CREATE TABLE team_tactics(id INTEGER PRIMARY KEY AUTOINCREMENT, team_id INTEGER NOT NULL REFERENCES teams(id), name TEXT NOT NULL, concept TEXT NOT NULL, traits TEXT NOT NULL);
CREATE TABLE team_rating_fields(id INTEGER PRIMARY KEY AUTOINCREMENT, team_id INTEGER NOT NULL REFERENCES teams(id), name TEXT NOT NULL, UNIQUE(team_id,name));
CREATE TABLE player_custom_ratings(player_id INTEGER NOT NULL REFERENCES players(id), field_id INTEGER NOT NULL REFERENCES team_rating_fields(id) ON DELETE CASCADE, score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 5), PRIMARY KEY(player_id,field_id));
CREATE TABLE team_basic_rating_fields(team_id INTEGER NOT NULL REFERENCES teams(id),key TEXT NOT NULL,name TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(team_id,key));
CREATE TABLE squads(id INTEGER PRIMARY KEY AUTOINCREMENT,team_id INTEGER NOT NULL REFERENCES teams(id),name TEXT NOT NULL,config TEXT NOT NULL,result TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE squad_shares(token TEXT PRIMARY KEY,squad_id INTEGER NOT NULL REFERENCES squads(id) ON DELETE CASCADE,snapshot TEXT NOT NULL);
CREATE TABLE team_formations(team_id INTEGER PRIMARY KEY REFERENCES teams(id),codes TEXT NOT NULL);
CREATE TABLE squad_outcomes(squad_id INTEGER NOT NULL REFERENCES squads(id),quarter INTEGER NOT NULL,outcome TEXT NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(squad_id,quarter));
CREATE TABLE IF NOT EXISTS app_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT OR IGNORE INTO app_revision VALUES(1,0);
CREATE TABLE IF NOT EXISTS app_write_guard(id INTEGER PRIMARY KEY CHECK(id=1),ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE IF NOT EXISTS auth_attempts(ip TEXT PRIMARY KEY,count INTEGER NOT NULL,until INTEGER NOT NULL);
